17	package org.springframework.samples.petclinic.util;
18	
19	import java.util.Map;
20	
21	/**
22	 * Decides whether a 4-digit postcode is valid for a city, using a fixed table of
23	 * inclusive postcode ranges keyed by the city's region (as resolved by
24	 * {@link LocalityResolver}). A city whose region is unknown accepts any 4-digit postcode.
25	 */
26	public final class PostcodePolicy {
27	
28	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
29	        "NSW", new int[] {2000, 2099},
30	        "VIC", new int[] {3000, 3099},
31	        "QLD", new int[] {4000, 4099});
32	
33	    private PostcodePolicy() {
34	    }
35	
36	    /**
37	     * Check whether the given 4-digit postcode falls within the range allowed for the
38	     * city's region.
39	     *
40	     * @param city the owner's city, may be {@code null}
41	     * @param postcode a 4-digit postcode string
42	     * @return {@code true} when the city's region is unknown, or the postcode is within
43	     * the region's inclusive range; {@code false} otherwise
44	     */
45	    public static boolean isValidForCity(String city, String postcode) {
46	        int[] range = REGION_POSTCODE_RANGE.get(LocalityResolver.resolve(city));
47	        if (range == null) {
48	            return true;
49	        }
50	        int value = Integer.parseInt(postcode);
51	        return value >= range[0] && value <= range[1];
52	    }
53	}
