1	package org.springframework.samples.petclinic.rest.validation;
2	
3	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
4	import org.springframework.samples.petclinic.util.PostcodePolicy;
5	
6	import jakarta.validation.ConstraintValidator;
7	import jakarta.validation.ConstraintValidatorContext;
8	
9	/**
10	 * Enforces {@link ValidPostcodeForCity}: a supplied 4-digit postcode must be valid for the
11	 * owner's city. An absent postcode is accepted (optional when absent), and a malformed
12	 * postcode is left to the field-level format constraint rather than reported here.
13	 */
14	public class ValidPostcodeForCityValidator implements ConstraintValidator<ValidPostcodeForCity, OwnerFieldsDto> {
15	
16	    @Override
17	    public boolean isValid(OwnerFieldsDto owner, ConstraintValidatorContext context) {
18	        if (owner == null) {
19	            return true;
20	        }
21	        String postcode = owner.getPostcode();
22	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
23	            return true;
24	        }
25	        if (PostcodePolicy.isValidForCity(owner.getCity(), postcode)) {
26	            return true;
27	        }
28	        context.disableDefaultConstraintViolation();
29	        context.buildConstraintViolationWithTemplate(context.getDefaultConstraintMessageTemplate())
30	            .addPropertyNode("postcode")
31	            .addConstraintViolation();
32	        return false;
33	    }
34	}
