15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	        expression = "java(org.springframework.samples.petclinic.util.PersonNameFormatter.displayName(owner.getFirstName(), owner.getLastName()))")
23	    @Mapping(target = "initials",
24	        expression = "java(org.springframework.samples.petclinic.util.PersonNameFormatter.initials(owner.getFirstName(), owner.getLastName()))")
25	    @Mapping(target = "membershipNumber",
26	        expression = "java(org.springframework.samples.petclinic.util.MembershipNumberFormatter.format(owner.getCustomerCode(), owner.getRegistrationDate()))")
27	    @Mapping(target = "membershipLevel",
28	        expression = "java(org.springframework.samples.petclinic.util.MembershipLevelFormatter.format(owner.getNamesakeCount(), owner.getEmail()))")
29	    @Mapping(target = "locality",
30	        expression = "java(org.springframework.samples.petclinic.util.LocalityResolver.resolve(owner.getCity()))")
31	    @Mapping(target = "contactPreference",
32	        expression = "java(org.springframework.samples.petclinic.util.ContactPreferenceResolver.resolve(owner.getEmail()))")
33	    @Mapping(target = "identityKey",
34	        expression = "java(org.springframework.samples.petclinic.util.OwnerIdentityKey.of(owner))")
35	    OwnerDto toOwnerDto(Owner owner);
36	
37	    Owner toOwner(OwnerDto ownerDto);
38	
39	    @Mapping(target = "id", ignore = true)
40	    @Mapping(target = "pets", ignore = true)
41	    @Mapping(target = "address",
42	        expression = "java(org.springframework.samples.petclinic.util.AddressNormalizer.normalize(ownerDto.getAddress()))")
43	    @Mapping(target = "telephone",
44	        expression = "java(org.springframework.samples.petclinic.util.TelephoneNormalizer.toE164(ownerDto.getTelephone()).orElse(null))")
45	    @Mapping(target = "email",
46	        expression = "java(org.springframework.samples.petclinic.util.EmailNormalizer.normalize(ownerDto.getEmail()))")
47	    Owner toOwner(OwnerFieldsDto ownerDto);
48	
49	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
50	
51	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
52	
53	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
54	        OwnerPageDto ownerPageDto = new OwnerPageDto();
55	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
56	        ownerPageDto.setPage(ownerPage.getNumber());
57	        ownerPageDto.setSize(ownerPage.getSize());
58	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
59	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
60	        return ownerPageDto;
61	    }
62	}
