1	package org.springframework.samples.petclinic.acceptance;
2	
3	import org.junit.jupiter.api.Test;
4	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
5	import tools.jackson.databind.node.ObjectNode;
6	
7	/** locality-postcode: locality is resolved by the postcode range first (NSW 2000-2099,
8	 * VIC 3000-3099, QLD 4000-4099), falling back to the city. A VIC-range postcode on an unknown city
9	 * therefore yields VIC, proving the postcode takes precedence. */
10	class AcceptanceTest extends AcceptanceBase {
11	
12		@Test
13		void coreRegionFromPostcodeRange() throws Exception {
14			int id = createOwnerOk(knownOwner("Sydney")); // postcode 2000 -> NSW
15			getOwner(id).andExpect(jsonPath("$.locality").value("NSW"));
16		}
17	
18		@Test
19		void functionalityPostcodePreferredOverCity() throws Exception {
20			ObjectNode o = ownerNode(); // random (unknown) city
21			o.put("postcode", "3000"); // VIC range
22			int id = createOwnerOk(o);
23			getOwner(id).andExpect(jsonPath("$.locality").value("VIC"));
24		}
25	}
