     * @return the matching region, or {@link Optional#empty()} when the postcode is
     * absent, non-numeric, or in no known range
     */
    public static Optional<String> regionForPostcode(String postcode) {
        if (postcode == null) {
            return Optional.empty();
        }
        int value;
